#!/bin/bash
set -e
echo "Building BioZig with biological net module..."
zig build-exe -ODebug --dep core --dep molecular --dep algorithms --dep analytics --dep ingestion --dep structural --dep visualization --dep cellular --dep population --dep reporting --dep net -Mroot=/Users/sulky/Desktop/biozig/cli/main.zig -ODebug -Mcore=/Users/sulky/Desktop/biozig/core/core.zig -ODebug --dep core -Mmolecular=/Users/sulky/Desktop/biozig/molecular/molecular.zig -ODebug --dep core --dep molecular --dep cellular --dep visualization --dep analytics -Malgorithms=/Users/sulky/Desktop/biozig/algorithms/algorithms.zig -ODebug --dep core -Manalytics=/Users/sulky/Desktop/biozig/analytics/analytics.zig -ODebug --dep core --dep molecular --dep cellular --dep structural --dep systems --dep visualization -Mingestion=/Users/sulky/Desktop/biozig/ingestion/ingestion.zig -ODebug --dep core --dep molecular -Mstructural=/Users/sulky/Desktop/biozig/structural/structural.zig -ODebug --dep core --dep structural -Mvisualization=/Users/sulky/Desktop/biozig/visualization/visualization.zig -ODebug --dep core --dep molecular -Mcellular=/Users/sulky/Desktop/biozig/cellular/cellular.zig -ODebug --dep core -Mpopulation=/Users/sulky/Desktop/biozig/population/population.zig -ODebug --dep core --dep visualization -Mreporting=/Users/sulky/Desktop/biozig/reporting/reporting.zig -ODebug -Mnet=/Users/sulky/Desktop/biozig/net/net.zig -ODebug --dep core --dep molecular --dep cellular -Msystems=/Users/sulky/Desktop/biozig/systems/systems.zig --cache-dir .zig-cache --global-cache-dir /Users/sulky/.cache/zig --name biozig --zig-lib-dir /Users/sulky/.zvm/master/lib/

echo "Running Live Streaming Benchmark (Human Chromosome 1 via NCBI)..."
/usr/bin/time -l ./biozig fetch --db ncbi --query "NC_000001.11" --analyze gc_content
